<?php include 'config.php'; $msg=''; if(isset($_GET['delete'])) mysqli_query($conn,'DELETE FROM products WHERE id='.(int)$_GET['delete']);
if($_SERVER['REQUEST_METHOD']=='POST'){ $name=trim($_POST['name']); $price=$_POST['price']; $qty=$_POST['quantity']; if($name==''||!is_numeric($price)||!is_numeric($qty)||$price<=0||$qty<0){$msg='Enter valid product details';} else { $id=(int)($_POST['id']??0); if($id>0){$stmt=mysqli_prepare($conn,'UPDATE products SET name=?,price=?,quantity=? WHERE id=?'); mysqli_stmt_bind_param($stmt,'sdii',$name,$price,$qty,$id);}else{$stmt=mysqli_prepare($conn,'INSERT INTO products(name,price,quantity) VALUES(?,?,?)'); mysqli_stmt_bind_param($stmt,'sdi',$name,$price,$qty);} mysqli_stmt_execute($stmt); }}
$res=mysqli_query($conn,'SELECT * FROM products ORDER BY id'); ?>
<!DOCTYPE html><html><head><title>Q12 Inventory</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Product Inventory Management</h1><p class="error"><?php echo $msg; ?></p><form method="post"><input name="id" placeholder="Product ID only for update"><input name="name" placeholder="Product Name"><input name="price" placeholder="Price"><input name="quantity" placeholder="Quantity"><button>Save Product</button></form><table><tr><th>ID</th><th>Name</th><th>Price</th><th>Qty</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($res)){ ?><tr><td><?php echo $r['id']; ?></td><td><?php echo $r['name']; ?></td><td><?php echo $r['price']; ?></td><td><?php echo $r['quantity']; ?></td><td><a onclick="return confirmDelete()" href="?delete=<?php echo $r['id']; ?>">Delete</a></td></tr><?php } ?></table></div><script src="script.js"></script></body></html>
